   307	/**
   308	 * Initialize expense info
   309	 * @param reportID to attach the transaction to
   310	 * @param policy
   311	 * @param isFromGlobalCreate
   312	 * @param iouRequestType one of manual/scan/distance
   313	 */
   314	function initMoneyRequest(reportID: string, policy: OnyxEntry<OnyxTypes.Policy>, isFromGlobalCreate: boolean, iouRequestType: IOURequestType = CONST.IOU.REQUEST_TYPE.MANUAL) {
   315	    // Generate a brand new transactionID
   316	    const newTransactionID = CONST.IOU.OPTIMISTIC_TRANSACTION_ID;
   317	    const currency = policy?.outputCurrency ?? currentUserPersonalDetails?.localCurrencyCode ?? CONST.CURRENCY.USD;
   318	    // Disabling this line since currentDate can be an empty string
   319	    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   320	    const created = currentDate || format(new Date(), 'yyyy-MM-dd');
   321	
   322	    const currentTransaction = allTransactionDrafts?.[`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`];
   323	
   324	    // in case we have to re-init money request, but the IOU request type is the same with the old draft transaction,
   325	    // we should keep most of the existing data by using the ONYX MERGE operation
   326	    if (currentTransaction?.iouRequestType === iouRequestType) {
   327	        // so, we just need to update the reportID, isFromGlobalCreate, created, currency
   328	        Onyx.merge(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`, {
   329	            reportID,
   330	            isFromGlobalCreate,
   331	            created,
   332	            currency,
   333	            transactionID: newTransactionID,
   334	        });
   335	        return;
   336	    }
   337	
   338	    const comment: Comment = {};
   339	
   340	    // Add initial empty waypoints when starting a distance expense
   341	    if (iouRequestType === CONST.IOU.REQUEST_TYPE.DISTANCE) {
   342	        comment.waypoints = {
   343	            waypoint0: {keyForList: 'start_waypoint'},
   344	            waypoint1: {keyForList: 'stop_waypoint'},
   345	        };
   346	        if (!isFromGlobalCreate) {
   347	            const customUnitRateID = DistanceRequestUtils.getCustomUnitRateID(reportID);
   348	            comment.customUnit = {customUnitRateID};
   349	        }
   350	    }
   351	
   352	    // Store the transaction in Onyx and mark it as not saved so it can be cleaned up later
   353	    // Use set() here so that there is no way that data will be leaked between objects when it gets reset
   354	    Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`, {
   355	        amount: 0,
   356	        comment,
   357	        created,
   358	        currency,
   359	        iouRequestType,
   360	        reportID,
   361	        transactionID: newTransactionID,
   362	        isFromGlobalCreate,
   363	        merchant: CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   364	        splitPayerAccountIDs: currentUserPersonalDetails ? [currentUserPersonalDetails.accountID] : undefined,
   365	    });
   366	}
