    96	        ...(isDraft && {amount: CONST.IOU.DEFAULT_AMOUNT}),
    97	        // Empty out errors when we're saving a new waypoint as this indicates the user is updating their input
    98	        errorFields: {
    99	            route: null,
   100	        },
   101	
   102	        // Clear the existing route so that we don't show an old route
   103	        routes: {
   104	            route0: {
   105	                // Clear the existing distance to recalculate next time
   106	                distance: null,
