   134	function removeWaypoint(transaction: OnyxEntry<Transaction>, currentIndex: string, isDraft?: boolean): Promise<void | void[]> {
   135	    // Index comes from the route params and is a string
   136	    const index = Number(currentIndex);
   137	    const existingWaypoints = transaction?.comment?.waypoints ?? {};
   138	    const totalWaypoints = Object.keys(existingWaypoints).length;
   139	
   140	    const waypointValues = Object.values(existingWaypoints);
   141	    const removed = waypointValues.splice(index, 1);
   142	    if (removed.length === 0) {
   143	        return Promise.resolve();
   144	    }
   145	
   146	    const isRemovedWaypointEmpty = removed.length > 0 && !TransactionUtils.waypointHasValidAddress(removed[0] ?? {});
   147	
   148	    // When there are only two waypoints we are adding empty waypoint back
   149	    if (totalWaypoints === 2 && (index === 0 || index === totalWaypoints - 1)) {
   150	        waypointValues.splice(index, 0, {});
   151	    }
   152	
   153	    const reIndexedWaypoints: WaypointCollection = {};
   154	    waypointValues.forEach((waypoint, idx) => {
   155	        reIndexedWaypoints[`waypoint${idx}`] = waypoint;
   156	    });
   157	
   158	    // Onyx.merge won't remove the null nested object values, this is a workaround
   159	    // to remove nested keys while also preserving other object keys
   160	    // Doing a deep clone of the transaction to avoid mutating the original object and running into a cache issue when using Onyx.set
   161	    let newTransaction: Transaction = {
   162	        // eslint-disable-next-line @typescript-eslint/non-nullable-type-assertion-style
   163	        ...(transaction as Transaction),
   164	        comment: {
   165	            ...transaction?.comment,
   166	            waypoints: reIndexedWaypoints,
   167	            customUnit: {
   168	                ...transaction?.comment?.customUnit,
   169	                quantity: null,
   170	            },
   171	        },
   172	        // We want to reset the amount only for draft transactions (when creating the expense).
   173	        // When modifying an existing transaction, the amount will be updated on the actual IOU update operation.
   174	        ...(isDraft && {amount: CONST.IOU.DEFAULT_AMOUNT}),
   175	    };
   176	
   177	    if (!isRemovedWaypointEmpty) {
   178	        newTransaction = {
   179	            ...newTransaction,
   180	            // Clear any errors that may be present, which apply to the old route
   181	            errorFields: {
   182	                route: null,
   183	            },
   184	            // Clear the existing route so that we don't show an old route
   185	            routes: {
   186	                route0: {
   187	                    // Clear the existing distance to recalculate next time
   188	                    distance: null,
   189	                    geometry: {
   190	                        coordinates: null,
   191	                    },
   192	                },
   193	            },
   194	        };
   195	    }
   196	    if (isDraft) {
   197	        return Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${transaction?.transactionID}`, newTransaction);
   198	    }
   199	    return Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION}${transaction?.transactionID}`, newTransaction);
   200	}
